-- Block client-side profile privilege escalation while retaining normal field edits.
REVOKE INSERT, UPDATE ON TABLE public.profiles FROM PUBLIC, anon, authenticated;
GRANT INSERT ("id", "name", "email", "height", "weight", "date_of_birth", "settings", "created_at", "updated_at", "steps_goal", "timezone", "weekly_workout_goal", "active_plan_id", "weekly_streak", "volume_target_next_week", "onboarding_step", "onboarding_completed_at", "onboarding_dismissed_at", "onboarding_stage2_completed_at", "onboarding_stage2_dismissed_at", "onboarding_stage3_completed_at", "onboarding_stage3_dismissed_at", "onboarding_stage2_triggered_at", "onboarding_stage3_triggered_at", "username", "username_lower", "visibility") ON TABLE public.profiles TO authenticated;
GRANT UPDATE ("id", "name", "email", "height", "weight", "date_of_birth", "settings", "created_at", "updated_at", "steps_goal", "timezone", "weekly_workout_goal", "active_plan_id", "weekly_streak", "volume_target_next_week", "onboarding_step", "onboarding_completed_at", "onboarding_dismissed_at", "onboarding_stage2_completed_at", "onboarding_stage2_dismissed_at", "onboarding_stage3_completed_at", "onboarding_stage3_dismissed_at", "onboarding_stage2_triggered_at", "onboarding_stage3_triggered_at", "username", "username_lower", "visibility") ON TABLE public.profiles TO authenticated;
-- TRUNCATE is not governed by RLS; do not grant relation-control privileges to clients.
REVOKE TRUNCATE, TRIGGER, REFERENCES ON ALL TABLES IN SCHEMA public FROM PUBLIC, anon, authenticated;
